 "content": "from collections import deque


def transform(grid):
    """Color strict interior 1-cells by the marker in their 4-connected nonzero component."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            markers = set()
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if grid[y][x] not in (0, 1):
                    markers.add(grid[y][x])
                for dy, dx in dirs:
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            if len(markers) == 1:
                color = next(iter(markers))
                for y, x in cells:
                    if grid[y][x] == 1 and all(0 <= y + dy < h and 0 <= x + dx < w and grid[y + dy][x + dx] != 0 for dy, dx in dirs):
                        out[y][x] = color
    return out
